@props([ 'items' => [], 'active' => null, 'variant' => 'underline', ]) @php $firstKey = !empty($items) ? ($items[0]['id'] ?? array_key_first($items)) : null; $activeTab = $active ?: $firstKey; $navClass = $variant === 'pills' ? 'ui-tabs-pills' : 'ui-tabs-nav'; @endphp <div class="ui-tabs-container" {{ $attributes }}><div class="{{ $navClass }}"> @foreach($items as $item) @php $itemId = is_array($item) ? ($item['id'] ?? '') : $item; $itemLabel = is_array($item) ? ($item['label'] ?? $itemId) : $item; $itemIcon = is_array($item) ? ($item['icon'] ?? null) : null; $isActive = ($itemId === $activeTab); @endphp <button type="button" class="ui-tab-btn {{ $isActive ? 'is-active' : '' }}" data-ui-tab-target="{{ $itemId }}" > @if($itemIcon) <i class="{{ $itemIcon }}"></i> @endif <span>{{ $itemLabel }}</span></button> @endforeach </div><div class="ui-tabs-content">{{ $slot }}</div></div>